//! Native modules generated from the wire model.
//!
//! A wire module of the model (`Uorc.Codec.*`) states the coder's named
//! quantities: each a parameterless `Nat` whose body is a numeral (a format
//! identity: an extent, a field width) or an expression over other named
//! quantities, and each constant table a parameterless `Bytes`. The native
//! implementation reads those quantities from a Rust module generated here
//! from the model's source, so it states none of them itself: the generated
//! file carries `// @generated by \`figures native\` from <module>`, and the
//! figures check regenerates it and rejects a copy that differs, so the
//! native values are always the model's.
//!
//! The generated module holds every quantity once, as `u128` with the body the
//! model gives it, and views of it for the integer types the native code works
//! in (a view lists the quantities whose value the type holds), plus `bits`,
//! the base-two logarithm of each power-of-two quantity (a shift by it is a
//! rescale by the quantity), derived by `trailing_zeros`.

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::Path;

/// The generated native modules: (output, model source).
pub const GENERATED: [(&str, &str); 6] = [
    (
        "crates/uorc/src/model/framing.rs",
        "src/Uorc/Search/FramingOrder.lex.tex",
    ),
    (
        "crates/uorc/src/model/frame.rs",
        "src/Uorc/Wire/Frame.lex.tex",
    ),
    (
        "crates/uorc/src/model/neuromorphic.rs",
        "src/Uorc/Neuromorphic.lex.tex",
    ),
    (
        "crates/uorc/src/model/ncm.rs",
        "client/src/Uorc/Codec/NcmEncode.lex.tex",
    ),
    (
        "crates/uorc/src/model/archive.rs",
        "client/src/Uorc/Codec/Archive.lex.tex",
    ),
    (
        "crates/uorc/src/model/x86.rs",
        "client/src/Uorc/Codec/X86.lex.tex",
    ),
];

/// The tool named on a generated file's first line.
pub const TOOL: &str = "`figures native`";

/// A body of a named quantity.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Expr {
    /// A numeral.
    Num(u128),
    /// Another named quantity.
    Name(String),
    /// An operation on two.
    Op(Op, Box<Expr>, Box<Expr>),
}

/// The operations a quantity's body uses.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Op {
    /// `a + b`.
    Add,
    /// `prim subtract a b` (a >= b in every body the model states).
    Sub,
    /// `prim multiply a b`.
    Mul,
    /// `prim quotient a b 0`.
    Div,
    /// `prim remainder a b 0`.
    Rem,
}

/// One definition of a wire module the generator carries.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Def {
    /// A named quantity.
    Nat(Expr),
    /// A constant table.
    Bytes(Vec<u8>),
}

fn field<'a>(decl: &'a str, key: &str) -> Option<&'a str> {
    crate::field(decl, key)
}

/// The parameterless `Nat` and `Bytes` definitions of a module's source, in
/// order; a body the generator does not read (a call, a match) is left out.
pub fn definitions(text: &str) -> Vec<(String, Def)> {
    let mut out = Vec::new();
    for decl in text.split("definition{").skip(1) {
        let decl = decl.split("\n}").next().unwrap_or(decl);
        if !decl.contains("parameters: [],") {
            continue;
        }
        let (Some(name), Some(result)) = (field(decl, "name"), field(decl, "result")) else {
            continue;
        };
        let Some(at) = decl.find("body: ") else {
            continue;
        };
        let rest = &decl[at + 6..];
        let body = match rest.find(",\n  ") {
            Some(e) => &rest[..e],
            // the one-line form: `definition{name: n, …, body: b}`
            None => rest
                .lines()
                .next()
                .unwrap_or(rest)
                .trim_end()
                .trim_end_matches('}'),
        }
        .trim();
        let def = match result {
            "Nat" => parse_expr(body).map(Def::Nat),
            "Bytes" => hex(body).map(Def::Bytes),
            _ => None,
        };
        if let Some(d) = def {
            out.push((name.to_string(), d));
        }
    }
    out
}

fn hex(s: &str) -> Option<Vec<u8>> {
    let h = s.strip_prefix("0x")?;
    if h.len() % 2 != 0 || !h.bytes().all(|b| b.is_ascii_hexdigit()) {
        return None;
    }
    (0..h.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&h[i..i + 2], 16).ok())
        .collect()
}

fn tokens(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut cur = String::new();
    for c in s.chars() {
        if c == '(' || c == ')' || c == '+' || c == ':' || c.is_whitespace() {
            if !cur.is_empty() {
                out.push(std::mem::take(&mut cur));
            }
            if !c.is_whitespace() {
                out.push(c.to_string());
            }
        } else {
            cur.push(c);
        }
    }
    if !cur.is_empty() {
        out.push(cur);
    }
    out
}

/// Parse a quantity's body: a numeral, `(name)`, `(a + b)`, or
/// `(prim subtract|multiply|quotient|remainder a b [0] : Nat)`.
pub fn parse_expr(s: &str) -> Option<Expr> {
    let t = tokens(s);
    let mut i = 0;
    let e = expr(&t, &mut i)?;
    (i == t.len()).then_some(e)
}

fn expr(t: &[String], i: &mut usize) -> Option<Expr> {
    let tok = t.get(*i)?;
    *i += 1;
    if let Ok(n) = tok.parse::<u128>() {
        return Some(Expr::Num(n));
    }
    if tok != "(" {
        return None;
    }
    let head = t.get(*i)?.clone();
    let e = if head == "prim" {
        *i += 1;
        let op = match t.get(*i)?.as_str() {
            "subtract" => Op::Sub,
            "multiply" => Op::Mul,
            "quotient" => Op::Div,
            "remainder" => Op::Rem,
            _ => return None,
        };
        *i += 1;
        let a = expr(t, i)?;
        let b = expr(t, i)?;
        if matches!(op, Op::Div | Op::Rem) {
            // the value at a zero divisor: the model's bodies give 0 and never divide by 0
            if t.get(*i)? != "0" {
                return None;
            }
            *i += 1;
        }
        if t.get(*i)? != ":" || t.get(*i + 1)? != "Nat" {
            return None;
        }
        *i += 2;
        Expr::Op(op, Box::new(a), Box::new(b))
    } else if head != "("
        && head.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
        && t.get(*i + 1).is_some_and(|x| x == ")")
    {
        *i += 1;
        Expr::Name(head)
    } else {
        let a = expr(t, i)?;
        if t.get(*i)? != "+" {
            return None;
        }
        *i += 1;
        let b = expr(t, i)?;
        Expr::Op(Op::Add, Box::new(a), Box::new(b))
    };
    if t.get(*i)? != ")" {
        return None;
    }
    *i += 1;
    Some(e)
}

/// The value of a body over the values known so far.
pub fn value(e: &Expr, known: &BTreeMap<String, u128>) -> Option<u128> {
    match e {
        Expr::Num(n) => Some(*n),
        Expr::Name(n) => known.get(n).copied(),
        Expr::Op(op, a, b) => {
            let (a, b) = (value(a, known)?, value(b, known)?);
            match op {
                Op::Add => a.checked_add(b),
                Op::Sub => a.checked_sub(b),
                Op::Mul => a.checked_mul(b),
                Op::Div => a.checked_div(b),
                Op::Rem => a.checked_rem(b),
            }
        }
    }
}

fn rust(e: &Expr) -> String {
    match e {
        Expr::Num(n) => n.to_string(),
        Expr::Name(n) => n.clone(),
        Expr::Op(op, a, b) => {
            let o = match op {
                Op::Add => "+",
                Op::Sub => "-",
                Op::Mul => "*",
                Op::Div => "/",
                Op::Rem => "%",
            };
            format!("({} {o} {})", rust(a), rust(b))
        }
    }
}

/// The integer views: (type, largest value it holds). `usize` is held to 32
/// bits, the narrowest target the client builds (wasm32).
const VIEWS: [(&str, u128); 9] = [
    ("u8", u8::MAX as u128),
    ("u16", u16::MAX as u128),
    ("u32", u32::MAX as u128),
    ("u64", u64::MAX as u128),
    ("usize", u32::MAX as u128),
    ("i16", i16::MAX as u128),
    ("i32", i32::MAX as u128),
    ("i64", i64::MAX as u128),
    ("i128", i128::MAX as u128),
];

/// A named quantity: name, body, value.
pub type Quantity = (String, Expr, u128);
/// A constant table: name, bytes.
pub type Table = (String, Vec<u8>);

/// The named quantities of a module's source, each with its body and value,
/// and its constant tables. Besides the quantities the model defines, each
/// extent it states as a numeral brings the characteristic quantities of its
/// domain the model's own pass derives (`client/gen/domains.py`): its last
/// value, its half (over the module's `radix`) and the half's last value,
/// named as that pass names them.
pub fn quantities(text: &str) -> (Vec<Quantity>, Vec<Table>) {
    let mut tables = Vec::new();
    let mut bodies = Vec::new();
    for (name, def) in definitions(text) {
        match def {
            Def::Nat(e) => bodies.push((name, e)),
            Def::Bytes(b) => tables.push((name, b)),
        }
    }
    // a body may read a quantity the module defines after it: evaluate to a fixpoint
    let mut known = BTreeMap::new();
    loop {
        let before = known.len();
        for (name, e) in &bodies {
            if !known.contains_key(name) {
                if let Some(v) = value(e, &known) {
                    known.insert(name.clone(), v);
                }
            }
        }
        if known.len() == before {
            break;
        }
    }
    let mut nats: Vec<Quantity> = bodies
        .into_iter()
        .filter_map(|(n, e)| known.get(&n).map(|v| (n, e, *v)))
        .collect();
    let radix = known.get(RADIX).copied();
    let extents: Vec<(String, u128)> = nats
        .iter()
        .filter(|(_, e, v)| matches!(e, Expr::Num(_)) && *v > 2)
        .map(|(n, _, v)| (n.clone(), *v))
        .collect();
    let name = |e: &str| Box::new(Expr::Name(e.to_string()));
    let one = || Box::new(Expr::Num(1));
    for (q, v) in extents {
        let mut add = |n: String, e: Expr, x: u128| {
            if x > 1 && !known.contains_key(&n) {
                known.insert(n.clone(), x);
                nats.push((n, e, x));
            }
        };
        add(
            format!("{q}Last"),
            Expr::Op(Op::Sub, name(&q), one()),
            v - 1,
        );
        if let Some(r) = radix.filter(|r| *r > 1 && v % *r == 0) {
            let half = format!("{q}Half");
            add(
                half.clone(),
                Expr::Op(Op::Div, name(&q), name(RADIX)),
                v / r,
            );
            add(
                format!("{q}HalfLast"),
                Expr::Op(Op::Sub, name(&half), one()),
                v / r - 1,
            );
        }
    }
    (nats, tables)
}

/// Each table read as big-endian cells of 2, 4 and 8 bytes (each width that
/// divides it): (table, width, cells).
pub fn table_cells(tables: &[(String, Vec<u8>)]) -> Vec<(String, usize, Vec<u128>)> {
    let mut out = Vec::new();
    for (name, b) in tables {
        for w in [2usize, 4, 8] {
            if b.len() % w == 0 && b.len() > w {
                let vs = b
                    .chunks(w)
                    .map(|c| c.iter().fold(0u128, |a, x| (a << 8) | u128::from(*x)))
                    .collect();
                out.push((name.clone(), w, vs));
            }
        }
    }
    out
}

/// The module's binary radix (the coder makes one decision per step).
pub const RADIX: &str = "radix";

/// The Rust module generated from a wire module's source.
pub fn generate(source: &str, text: &str) -> String {
    let module = source
        .trim_start_matches("client/src/")
        .trim_start_matches("src/")
        .trim_end_matches(".lex.tex")
        .replace('/', ".");
    let (nats, tables) = quantities(text);
    let mut s = String::new();
    let _ = writeln!(s, "// @generated by {TOOL} from {source}; do not edit.");
    let _ = writeln!(
        s,
        "//! The named quantities and constant tables of `{module}`, as the model states them.\n//!\n//! Each quantity is the model's body over the others; a view module per\n//! integer type lists those the type holds, and [`bits`] the base-two\n//! logarithm of each power of two."
    );
    let _ = writeln!(s, "#![allow(non_upper_case_globals, dead_code, unused_parens, clippy::all, clippy::pedantic)]\n");
    for (name, e, _) in &nats {
        let _ = writeln!(
            s,
            "/// `{module}::{name}`.\npub const {name}: u128 = {};",
            rust(e)
        );
    }
    for (name, b) in &tables {
        let bytes: Vec<String> = b.iter().map(|x| format!("{x:#04x}")).collect();
        let _ = writeln!(
            s,
            "/// `{module}::{name}`.\npub const {name}: [u8; {}] = [{}];",
            b.len(),
            bytes.join(", ")
        );
    }
    let cells = table_cells(&tables);
    if !cells.is_empty() {
        let _ = writeln!(
            s,
            "\n/// The `n` big-endian cells of `w` bytes of a table.\nconst fn cells<const N: usize>(b: &[u8], w: usize) -> [u128; N] {{\n    let mut o = [0u128; N];\n    let mut i = 0;\n    while i < N {{\n        let mut j = 0;\n        while j < w {{\n            o[i] = (o[i] << u8::BITS) | b[i * w + j] as u128;\n            j += 1;\n        }}\n        i += 1;\n    }}\n    o\n}}"
        );
        for (name, w, vs) in &cells {
            let _ = writeln!(
                s,
                "/// `{module}::{name}` read as cells of {w} bytes.\npub const {name}Cells{w}: [u128; {n}] = cells::<{n}>(&{name}, {w});",
                n = vs.len()
            );
        }
    }
    for (ty, max) in VIEWS {
        let _ = writeln!(s, "\n/// The quantities a `{ty}` holds.\npub mod {ty} {{");
        for (name, _, v) in &nats {
            if v <= &max {
                let _ = writeln!(s, "    pub const {name}: {ty} = super::{name} as {ty};");
            }
        }
        for (name, w, vs) in &cells {
            if vs.iter().all(|v| v <= &max) {
                let n = vs.len();
                let _ = writeln!(
                    s,
                    "    pub const {name}Cells{w}: [{ty}; {n}] = {{\n        let c = super::{name}Cells{w};\n        let mut o = [0; {n}];\n        let mut i = 0;\n        while i < {n} {{\n            o[i] = c[i] as {ty};\n            i += 1;\n        }}\n        o\n    }};"
                );
            }
        }
        let _ = writeln!(s, "\n    /// The base-two logarithm of each power-of-two quantity, as a `{ty}`.\n    pub mod bits {{");
        for (name, _, v) in &nats {
            if v.is_power_of_two() {
                let _ = writeln!(s, "        pub const {name}: {ty} = super::super::{name}.trailing_zeros() as {ty};");
            }
        }
        let _ = writeln!(s, "    }}\n}}");
    }
    let _ = writeln!(
        s,
        "\n/// The base-two logarithm of each power-of-two quantity.\npub mod bits {{"
    );
    for (name, _, v) in &nats {
        if v.is_power_of_two() {
            let _ = writeln!(
                s,
                "    pub const {name}: u32 = super::{name}.trailing_zeros();"
            );
        }
    }
    let _ = writeln!(s, "}}");
    s
}

/// Regenerate every native module (`figures native`).
pub fn write(root: &Path) -> Result<(), crate::Error> {
    for (out, src) in GENERATED {
        let text = std::fs::read_to_string(root.join(src)).map_err(|e| format!("{src}: {e}"))?;
        let path = root.join(out);
        if let Some(dir) = path.parent() {
            std::fs::create_dir_all(dir).map_err(|e| format!("{out}: {e}"))?;
        }
        std::fs::write(&path, generate(src, &text)).map_err(|e| format!("{out}: {e}"))?;
    }
    Ok(())
}

/// The generated modules that differ from their source's generation.
pub fn stale(root: &Path) -> Vec<String> {
    let mut out = Vec::new();
    for (file, src) in GENERATED {
        // A missing module is the compiler's to reject (`mod model` names it).
        if !root.join(file).exists() {
            continue;
        }
        let want = std::fs::read_to_string(root.join(src)).map(|t| generate(src, &t));
        let have = std::fs::read_to_string(root.join(file));
        match (want, have) {
            (Ok(w), Ok(h)) if w == h => {}
            (Err(e), _) => out.push(format!("{src}: {e}")),
            _ => out.push(format!(
                "{file} is not the generation of {src}; regenerate it with `just figures-native`"
            )),
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bodies_parse_and_evaluate() {
        let text = "definition{\n  name: r,\n  parameters: [],\n  result: Nat,\n  body: 4096,\n  executable: true,\n  axioms: []\n}\n\
                    definition{\n  name: h,\n  parameters: [],\n  result: Nat,\n  body: (prim quotient (r) (two) 0 : Nat),\n  executable: true,\n  axioms: []\n}\n\
                    definition{\n  name: two,\n  parameters: [],\n  result: Nat,\n  body: 2,\n  executable: true,\n  axioms: []\n}\n\
                    definition{\n  name: z,\n  parameters: [],\n  result: Nat,\n  body: (prim quotient (r) (none) 0 : Nat),\n  executable: true,\n  axioms: []\n}\n\
                    definition{\n  name: l,\n  parameters: [],\n  result: Nat,\n  body: (prim subtract ((r) + (r)) 1 : Nat),\n  executable: true,\n  axioms: []\n}\n\
                    definition{\n  name: t,\n  parameters: [],\n  result: Bytes,\n  body: 0x0102,\n  executable: true,\n  axioms: []\n}";
        let d = definitions(text);
        assert_eq!(d.len(), 6);
        let g = generate("client/src/Uorc/Codec/X.lex.tex", text);
        assert!(g.starts_with(
            "// @generated by `figures native` from client/src/Uorc/Codec/X.lex.tex;"
        ));
        assert!(g.contains("pub const l: u128 = ((r + r) - 1);"));
        assert!(g.contains("pub const t: [u8; 2] = [0x01, 0x02];"));
        // h reads two before the model defines it; z reads a quantity the module does not define
        assert!(g.contains("pub const h: u128 = (r / two);"));
        assert!(!g.contains("pub const z"));
        assert!(g.contains("    pub const r: u32 = super::r.trailing_zeros();"));
    }
}
